func (c *Client) applyEditors(ctx context.Context, req *http.Request, additionalEditors []RequestEditorFn) error {
	for _, r := range c.RequestEditors {
		if err := r(ctx, req); err != nil {
			return err
		}
	}
	for _, r := range additionalEditors {
		if err := r(ctx, req); err != nil {
			return err
		}
	}
	return nil
}

// ClientWithResponses builds on ClientInterface to offer response payloads
type ClientWithResponses struct {
	ClientInterface
}

// NewClientWithResponses creates a new ClientWithResponses, which wraps
// Client with return type handling
func NewClientWithResponses(server string, opts ...ClientOption) (*ClientWithResponses, error) {
	client, err := NewClient(server, opts...)
	if err != nil {
		return nil, err
	}
	return &ClientWithResponses{client}, nil
}

// WithBaseURL overrides the baseURL.
func WithBaseURL(baseURL string) ClientOption {
	return func(c *Client) error {
		newBaseURL, err := url.Parse(baseURL)
		if err != nil {
			return err
		}
		c.Server = newBaseURL.String()
		return nil
	}
}

// ClientWithResponsesInterface is the interface specification for the client with responses above.
type ClientWithResponsesInterface interface {

	// ExtractFeatureWithBodyWithResponse Извлечь цифровой признак без добавления в галерею
	//
	// Нулевой или нечисловой вектор не является допустимым эмбеддингом.
	// Невалидный BBox отклоняется до вызова модели. Некорректный результат
	// модели возвращается как 503 с кодом dependency_unavailable.
	//
	// Takes any type of body and a specified content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /api/v1/features (the `ExtractFeature` operationId).
	ExtractFeatureWithBodyWithResponse(ctx context.Context, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*ExtractFeatureResponse, error)

	// ExtractFeatureWithResponse Извлечь цифровой признак без добавления в галерею
	//
	// Нулевой или нечисловой вектор не является допустимым эмбеддингом.
	// Невалидный BBox отклоняется до вызова модели. Некорректный результат
	// модели возвращается как 503 с кодом dependency_unavailable.
	//
	// Takes a body of the `application/json` content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /api/v1/features (the `ExtractFeature` operationId).
	ExtractFeatureWithResponse(ctx context.Context, body ExtractFeatureJSONRequestBody, reqEditors ...RequestEditorFn) (*ExtractFeatureResponse, error)

	// ListObservationsWithResponse Просмотреть галерею
	//
	// Сортировка created_at DESC, id DESC. Непрозрачный курсор продолжает
	// выборку после последней пары значений; это не снимок данных.
	// Некорректный курсор возвращает 400. total не вычисляется.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /api/v1/gallery/observations (the `ListObservations` operationId).
	ListObservationsWithResponse(ctx context.Context, params *ListObservationsParams, reqEditors ...RequestEditorFn) (*ListObservationsResponse, error)

	// CreateObservationWithBodyWithResponse Вычислить признак и добавить объект в галерею
	//
	// Наблюдение — конкретный BBox на кадре, не установленная идентичность ТС.
	// Разные BBox одного photo_id сохраняются как независимые наблюдения.
	// Повторный запрос создаёт новое наблюдение. 201 означает, что вектор
	// сохранён и наблюдение доступно для поиска. Нулевой/нечисловой результат
	// модели возвращает 503 и не сохраняется.
	//
	// Takes any type of body and a specified content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /api/v1/gallery/observations (the `CreateObservation` operationId).
	CreateObservationWithBodyWithResponse(ctx context.Context, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*CreateObservationResponse, error)

	// CreateObservationWithResponse Вычислить признак и добавить объект в галерею
	//
	// Наблюдение — конкретный BBox на кадре, не установленная идентичность ТС.
	// Разные BBox одного photo_id сохраняются как независимые наблюдения.
	// Повторный запрос создаёт новое наблюдение. 201 означает, что вектор
	// сохранён и наблюдение доступно для поиска. Нулевой/нечисловой результат
	// модели возвращает 503 и не сохраняется.
	//
	// Takes a body of the `application/json` content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /api/v1/gallery/observations (the `CreateObservation` operationId).
	CreateObservationWithResponse(ctx context.Context, body CreateObservationJSONRequestBody, reqEditors ...RequestEditorFn) (*CreateObservationResponse, error)

	// DeleteObservationWithResponse Удалить наблюдение из поиска
	//
	// Удаляет наблюдение и эмбеддинг, сохраняя исходный кадр.
	// Повторное удаление отсутствующего UUID также возвращает 204.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with DELETE /api/v1/gallery/observations/{observation_id} (the `DeleteObservation` operationId).
	DeleteObservationWithResponse(ctx context.Context, observationId ObservationID, reqEditors ...RequestEditorFn) (*DeleteObservationResponse, error)

	// GetObservationWithResponse Получить наблюдение галереи
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /api/v1/gallery/observations/{observation_id} (the `GetObservation` operationId).
	GetObservationWithResponse(ctx context.Context, observationId ObservationID, reqEditors ...RequestEditorFn) (*GetObservationResponse, error)

	// UploadPhotoWithBodyWithResponse Загрузить полный кадр JPEG или PNG
	//
	// Один файл до 10 MiB (10485760 байт), не более 40000000 пикселей.
	// Проверяются фактический формат и возможность декодирования; расширению
	// и заявленному Content-Type доверять нельзя. EXIF-ориентация не применяется:
	// BBox задаётся в координатах исходной декодированной матрицы пикселей.
	// Ответ возвращается после сохранения файла и метаданных.
	// Повторная загрузка создаёт новый ресурс; дедупликация не гарантируется.
	//
	// Takes any type of body and a specified content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /api/v1/photos (the `UploadPhoto` operationId).
	UploadPhotoWithBodyWithResponse(ctx context.Context, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*UploadPhotoResponse, error)

	// GetPhotoWithResponse Получить метаданные кадра
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /api/v1/photos/{photo_id} (the `GetPhoto` operationId).
	GetPhotoWithResponse(ctx context.Context, photoId PhotoID, reqEditors ...RequestEditorFn) (*GetPhotoResponse, error)

	// DownloadPhotoWithResponse Получить исходный кадр для отображения результатов
	//
	// Бэкенд читает приватный объект MinIO; внутренние ключи S3 не раскрываются.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /api/v1/photos/{photo_id}/content (the `DownloadPhoto` operationId).
	DownloadPhotoWithResponse(ctx context.Context, photoId PhotoID, reqEditors ...RequestEditorFn) (*DownloadPhotoResponse, error)

	// SearchVehiclesWithBodyWithResponse Найти похожие автомобили или вернуть отказ
	//
	// Запрос не добавляется в галерею. Сходство — cosine similarity в [-1, 1],
	// больше означает ближе; это не калиброванная вероятность. Для pgvector
	// score = 1 - cosine_distance. Результаты сортируются по confidence DESC,
	// при равенстве — observation.id ASC. Возвращается не более top_k объектов.
	// candidates: включаются только confidence >= threshold (по умолчанию 0.36).
	// Пустой список означает refused=true; причина empty_gallery, если после
	// исключений галерея пуста, иначе below_threshold.
	// ranking: порог не применяется; возвращаются ближайшие объекты, даже
	// при низкой уверенности; refused всегда false, refusal_reason=null,
	// threshold=null. Это режим подготовки top-10 для submission.csv.
	// Результаты относятся к наблюдениям и не объединяются по vehicle_id.
	// Поиск использует ANN/HNSW, поэтому полнота ближайших соседей приближённая.
	// Нулевой/нечисловой результат модели — ошибка 503, а не отказ.
	//
	// Takes any type of body and a specified content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /api/v1/search (the `SearchVehicles` operationId).
	SearchVehiclesWithBodyWithResponse(ctx context.Context, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*SearchVehiclesResponse, error)

	// SearchVehiclesWithResponse Найти похожие автомобили или вернуть отказ
	//
	// Запрос не добавляется в галерею. Сходство — cosine similarity в [-1, 1],
	// больше означает ближе; это не калиброванная вероятность. Для pgvector
	// score = 1 - cosine_distance. Результаты сортируются по confidence DESC,
	// при равенстве — observation.id ASC. Возвращается не более top_k объектов.
	// candidates: включаются только confidence >= threshold (по умолчанию 0.36).
	// Пустой список означает refused=true; причина empty_gallery, если после
	// исключений галерея пуста, иначе below_threshold.
	// ranking: порог не применяется; возвращаются ближайшие объекты, даже
	// при низкой уверенности; refused всегда false, refusal_reason=null,
	// threshold=null. Это режим подготовки top-10 для submission.csv.
	// Результаты относятся к наблюдениям и не объединяются по vehicle_id.
	// Поиск использует ANN/HNSW, поэтому полнота ближайших соседей приближённая.
	// Нулевой/нечисловой результат модели — ошибка 503, а не отказ.
	//
	// Takes a body of the `application/json` content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /api/v1/search (the `SearchVehicles` operationId).
	SearchVehiclesWithResponse(ctx context.Context, body SearchVehiclesJSONRequestBody, reqEditors ...RequestEditorFn) (*SearchVehiclesResponse, error)

	// GetHealthWithResponse Проверка работоспособности HTTP-процесса
	//
	// Не проверяет готовность ML, PostgreSQL и MinIO.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /healthz (the `GetHealth` operationId).
	GetHealthWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*GetHealthResponse, error)

	// GetOpenAPIDocumentWithResponse Получить актуальный контракт API
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /openapi.json (the `GetOpenAPIDocument` operationId).
	GetOpenAPIDocumentWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*GetOpenAPIDocumentResponse, error)

	// GetReadinessWithResponse Проверка готовности всех зависимостей
	//
	// Успех только при доступности PostgreSQL, MinIO и загруженной ML-модели.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /readyz (the `GetReadiness` operationId).
	GetReadinessWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*GetReadinessResponse, error)
}

