// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ExtractFeature Извлечь цифровой признак без добавления в галерею
	// (POST /api/v1/features)
	ExtractFeature(ctx context.Context, request ExtractFeatureRequestObject) (ExtractFeatureResponseObject, error)
	// ListObservations Просмотреть галерею
	// (GET /api/v1/gallery/observations)
	ListObservations(ctx context.Context, request ListObservationsRequestObject) (ListObservationsResponseObject, error)
	// CreateObservation Вычислить признак и добавить объект в галерею
	// (POST /api/v1/gallery/observations)
	CreateObservation(ctx context.Context, request CreateObservationRequestObject) (CreateObservationResponseObject, error)
	// DeleteObservation Удалить наблюдение из поиска
	// (DELETE /api/v1/gallery/observations/{observation_id})
	DeleteObservation(ctx context.Context, request DeleteObservationRequestObject) (DeleteObservationResponseObject, error)
	// GetObservation Получить наблюдение галереи
	// (GET /api/v1/gallery/observations/{observation_id})
	GetObservation(ctx context.Context, request GetObservationRequestObject) (GetObservationResponseObject, error)
	// UploadPhoto Загрузить полный кадр JPEG или PNG
	// (POST /api/v1/photos)
	UploadPhoto(ctx context.Context, request UploadPhotoRequestObject) (UploadPhotoResponseObject, error)
	// GetPhoto Получить метаданные кадра
	// (GET /api/v1/photos/{photo_id})
	GetPhoto(ctx context.Context, request GetPhotoRequestObject) (GetPhotoResponseObject, error)
	// DownloadPhoto Получить исходный кадр для отображения результатов
	// (GET /api/v1/photos/{photo_id}/content)
	DownloadPhoto(ctx context.Context, request DownloadPhotoRequestObject) (DownloadPhotoResponseObject, error)
	// SearchVehicles Найти похожие автомобили или вернуть отказ
	// (POST /api/v1/search)
	SearchVehicles(ctx context.Context, request SearchVehiclesRequestObject) (SearchVehiclesResponseObject, error)
	// GetHealth Проверка работоспособности HTTP-процесса
	// (GET /healthz)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// GetOpenAPIDocument Получить актуальный контракт API
	// (GET /openapi.json)
	GetOpenAPIDocument(ctx context.Context, request GetOpenAPIDocumentRequestObject) (GetOpenAPIDocumentResponseObject, error)
	// GetReadiness Проверка готовности всех зависимостей
	// (GET /readyz)
	GetReadiness(ctx context.Context, request GetReadinessRequestObject) (GetReadinessResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

